extends RefCounted

# Minimal Archetype-Based Entity Component System
# Encodes an entity handle as: (generation << 16) | slot_index.
const MAX_ENTITIES := 1 << 16
const INDEX_BITS := 16
const INDEX_MASK := MAX_ENTITIES - 1
const INVALID_ENTITY := -1

# slot_generation[s] is the current generation for slot s. Incremented each
# time the slot is freed; never wraps (within 16 bits), ensuring a recycled
# slot always gets a fresh generation. Initialized to 0.
var slot_generation := PackedInt32Array()
# slot_types[s] holds the PackedStringArray of component types (sorted) for
# the entity living in slot s, or null if the slot is free.
var slot_types := []
# free_slots tracks available slots for reuse (LIFO).
var free_slots := PackedInt32Array()
# archetypes[types_key] -> { "entities": { handle: { type: data } } }.
# keys are PackedStringArray objects.
var archetypes := {}

func _init() -> void:
	slot_generation.resize(MAX_ENTITIES)
	slot_types.resize(MAX_ENTITIES)
	# Initially all slots are free in ascending order. Popping from the end
	# means slot 0 is the first to be used.
	free_slots.resize(MAX_ENTITIES)
	for i in range(MAX_ENTITIES):
		slot_types[i] = null
		free_slots[i] = MAX_ENTITIES - 1 - i
	# Ensure the empty archetype always exists.
	archetypes[PackedStringArray()] = { "entities": {} }

func _alive(s: int, gen: int) -> bool:
	return slot_generation[s] == gen

func get_index(entity: int) -> int:
	return entity & INDEX_MASK

func get_generation(entity: int) -> int:
	return entity >> INDEX_BITS

func is_alive(entity: int) -> bool:
	var s := get_index(entity)
	if s < 0 or s >= MAX_ENTITIES: return false
	return _alive(s, get_generation(entity))

func create_entity() -> int:
	if free_slots.is_empty():
		return INVALID_ENTITY
	var s := free_slots[free_slots.size() - 1]
	free_slots.resize(free_slots.size() - 1)
	var gen := slot_generation[s]
	var handle := (gen << INDEX_BITS) | s
	slot_types[s] = PackedStringArray()
	archetypes[PackedStringArray()].entities[handle] = {}
	return handle

func destroy_entity(entity: int) -> bool:
	var s := get_index(entity)
	if s < 0 or s >= MAX_ENTITIES: return false
	if not _alive(s, get_generation(entity)): return false
	var types := slot_types[s] as PackedStringArray
	var archetype = archetypes.get(types)
	# Remove this entity's data from its archetype.
	if archetype:
		archetype.entities.erase(entity)
	slot_types[s] = null
	slot_generation[s] = (slot_generation[s] + 1) & 0xffff
	free_slots.append(s)
	return true

func has_component(entity: int, component_type: StringName) -> bool:
	var s := get_index(entity)
	if s < 0 or s >= MAX_ENTITIES: return false
	if not _alive(s, get_generation(entity)): return false
	return (slot_types[s] as PackedStringArray).has(component_type)

func get_component(entity: int, component_type: StringName) -> Variant:
	var s := get_index(entity)
	if s < 0 or s >= MAX_ENTITIES: return null
	if not _alive(s, get_generation(entity)): return null
	var types := slot_types[s] as PackedStringArray
	if not types.has(component_type): return null
	return archetypes[types].entities[entity][component_type]

func get_component_types(entity: int) -> Variant:
	var s := get_index(entity)
	if s < 0 or s >= MAX_ENTITIES: return null
	if not _alive(s, get_generation(entity)): return null
	return Array(slot_types[s] as PackedStringArray)

func add_component(entity: int, component_type: StringName, data: Dictionary) -> bool:
	var s := get_index(entity)
	if s < 0 or s >= MAX_ENTITIES: return false
	if not _alive(s, get_generation(entity)): return false
	var types := slot_types[s] as PackedStringArray
	if types.has(component_type):
		# Replace data, archetype unchanged.
		archetypes[types].entities[entity][component_type] = data.duplicate(true)
		return true
	# Migrate to a new archetype.
	var new_types := types.duplicate()
	new_types.append(component_type)
	new_types.sort()
	_migrate(entity, types, new_types, component_type, data)
	slot_types[s] = new_types
	return true

func remove_component(entity: int, component_type: StringName) -> bool:
	var s := get_index(entity)
	if s < 0 or s >= MAX_ENTITIES: return false
	if not _alive(s, get_generation(entity)): return false
	var types := slot_types[s] as PackedStringArray
	if not types.has(component_type): return false
	var new_types := PackedStringArray()
	for t in types:
		if t != component_type:
			new_types.append(t)
	new_types.sort()
	_migrate(entity, types, new_types, null, null)
	slot_types[s] = new_types
	return true

func _migrate(entity: int, from_types: PackedStringArray, to_types: PackedStringArray, new_type, new_data) -> void:
	# Ensure the destination archetype exists.
	if not archetypes.has(to_types):
		archetypes[to_types] = { "entities": {} }
	var old_archetype = archetypes[from_types]
	var to_archetype = archetypes[to_types]
	# Preserve all existing component data.
	var data := old_archetype.entities[entity] as Dictionary
	if new_type != null:
		data[new_type] = new_data.duplicate(true)
	to_archetype.entities[entity] = data
	old_archetype.entities.erase(entity)

func _sort_handles(a, b) -> bool:
	return get_index(a) < get_index(b)

func query(required_types: Array) -> Array:
	var req := PackedStringArray()
	for t in required_types:
		if t is StringName and not req.has(t):
			req.append(t)
	req.sort()
	var matches := []
	for types in archetypes:
		var ok := true
		for r in req:
			if not types.has(r):
				ok = false
				break
		if ok:
			for handle in (archetypes[types].entities as Dictionary):
				matches.append(handle)
	matches.sort_custom(Callable(self, "_sort_handles"))
	return matches

func get_entities_with_exact_types(types: Array) -> Array:
	var tarr := PackedStringArray()
	for t in types:
		if t is StringName:
			tarr.append(t)
	tarr.sort()
	if not archetypes.has(tarr):
		return []
	var matches := []
	for handle in (archetypes[tarr].entities as Dictionary):
		matches.append(handle)
	matches.sort_custom(Callable(self, "_sort_handles"))
	return matches

