	var types = w.get_component_types(e1)
	_assert(types.size() == 2, "2 types")
	var sorted_types = Array(types).duplicate()
	sorted_types.sort()
	_eq(types, sorted_types, "types sorted")
	_assert(w.remove_component(e1, &"Pos"), "remove pos")
	_assert(w.has_component(e1, &"Vel"), "still has vel")
	_assert(not w.has_component(e1, &"Pos"), "no longer pos")
	_eq(w.get_component_types(e1), [&"Vel"], "types after remove")
	_eq(w.get_component(e1, &"Pos"), null, "get removed comp")
	var e3 = w.create_entity()
	var s3 = w.get_index(e3)
	_assert(w.destroy_entity(e3), "destroy e3")
	_assert(not w.is_alive(e3), "e3 dead")
	_assert(w.add_component(e3, &"A", {}) == false, "stale add rejects")
	_eq(w.get_component(e3, &"A"), null, "stale get rejects")
	_assert(w.has_component(e3, &"A") == false, "stale has rejects")
	_eq(w.get_component_types(e3), null, "stale types rejects")
	_assert(w.destroy_entity(e3) == false, "re-destroy rejects")
	var w2 = World.new()
	var ea = w2.create_entity()
	var ga = w2.get_generation(ea)
	_assert(w2.destroy_entity(ea), "destroy ea")
	var eb = w2.create_entity()
	_eq(w2.get_index(eb), w2.get_index(ea), "reused slot")
	_assert(w2.get_generation(eb) != ga, "fresh generation")
	_assert(w2.is_alive(eb), "eb alive")
	_assert(not w2.is_alive(ea), "ea still dead")
	_eq(w2.get_component(ea, &"Pos"), null, "stale get rejects 2")
	_assert(w2.has_component(ea, &"Pos") == false, "stale has rejects 2")
	_assert(w2.destroy_entity(ea) == false, "stale destroy rejects 2")
	_assert(w2.add_component(ea, &"Pos", {}) == false, "stale add rejects 2")
	_assert(w2.remove_component(ea, &"Pos") == false, "stale remove rejects 2")
	var q = World.new()
	var qa = q.create_entity()
	var qb = q.create_entity()
	var qc = q.create_entity()
	q.add_component(qa, &"A", {}); q.add_component(qa, &"B", {})
	q.add_component(qb, &"A", {})
	q.add_component(qc, &"B", {})
	var r1 = q.query([&"A"])
	_eq(r1.size(), 2, "query A size")
	_assert(r1.has(qa) and r1.has(qb), "query A contains qa,qb")
	var r2 = q.query([&"B"])
	_eq(r2.size(), 2, "query B size")
	_assert(r2.has(qa) and r2.has(qc), "query B contains qa,qc")
	var r3 = q.query([&"A", &"B"])
	_eq(r3.size(), 1, "query AB size")
	_eq(r3[0], qa, "query AB contains qa")
	var r4 = q.query([])
	_eq(r4.size(), 3, "query all size")
	_eq(q.get_entities_with_exact_types([&"A", &"B"]), [qa], "exact AB")
	_eq(q.get_entities_with_exact_types([&"A"]), [qb], "exact A")
	_eq(q.get_entities_with_exact_types([&"B"]), [qc], "exact B")
	_eq(q.get_entities_with_exact_types([]), [], "exact empty")
	var qd = q.create_entity()
	_eq(q.get_entities_with_exact_types([]), [qd], "exact empty after add")
	if failures == 0:
		prints("ALL TESTS PASSED")
		get_tree().quit(0)
	else:
		prints("TESTS FAILED:", failures)
		get_tree().quit(1)

